import datetime as dt
def isg(d, n, dt=dt):
    while n:
        d += dt.timedelta(days=1)
        if d.weekday() < 5:
            n -= 1
    return d
def isg_say(bas, bit, dt=dt):
    n = 0
    d = bas
    while d <= bit:
        if d.weekday() < 5:
            n += 1
        d += dt.timedelta(days=1)
    return n
